 namespace Pterodactyl\Services\Dezerx\Ai; use Throwable; use Pterodactyl\Models\User; use Illuminate\Support\Facades\Crypt; use Pterodactyl\Services\Dezerx\Settings; class Ai { public const SETTING_KEY = 'ai'; public const KEY_MODES = ['panel', 'user', 'choice']; private const USER_KEY = 'ai'; private const CATALOG = ['anthropic' => ['base' => '', 'model' => 'claude-sonnet-5', 'label' => 'Anthropic (Claude)'], 'openai' => ['base' => '', 'model' => 'gpt-4.1', 'label' => 'OpenAI'], 'gemini' => ['base' => 'https://generativelanguage.googleapis.com/v1beta/openai', 'model' => 'gemini-flash-latest', 'label' => 'Google Gemini'], 'xai' => ['base' => 'https://api.x.ai/v1', 'model' => 'grok-4', 'label' => 'xAI (Grok)'], 'deepseek' => ['base' => 'https://api.deepseek.com/v1', 'model' => 'deepseek-chat', 'label' => 'DeepSeek'], 'opencode' => ['base' => 'https://opencode.ai/zen/v1', 'model' => '', 'label' => 'OpenCode Zen'], 'opencode-go' => ['base' => 'https://opencode.ai/zen/go/v1', 'model' => '', 'label' => 'OpenCode Go'], 'openrouter' => ['base' => 'https://openrouter.ai/api/v1', 'model' => '', 'label' => 'OpenRouter'], 'groq' => ['base' => 'https://api.groq.com/openai/v1', 'model' => '', 'label' => 'Groq'], 'mistral' => ['base' => 'https://api.mistral.ai/v1', 'model' => '', 'label' => 'Mistral'], 'ollama' => ['base' => 'http://localhost:11434/v1', 'model' => '', 'label' => 'Ollama (local)', 'keyless' => true, 'local' => true], 'custom' => ['base' => '', 'model' => '', 'label' => 'Anything OpenAI-compatible']]; public const DEFAULT_PROMPT = <<<'TEXT'
