    TEXT; public static function providers(): array { return array_keys(self::CATALOG); } public static function providerLabels(): array { return array_map(fn(array $entry) => $entry['label'], self::CATALOG); } public static function enabled(): bool { return (bool) self::setting('enabled', false); } public static function provider(): string { $provider = (string) self::setting('provider', 'anthropic'); return isset(self::CATALOG[$provider]) ? $provider : 'anthropic'; } public static function model(): string { $model = trim((string) self::setting('model', '')); return $model !== '' ? $model : self::defaultModel(self::provider()); } public static function modelFor(string $provider): string { return $provider === self::provider() ? self::model() : self::defaultModel($provider); } public static function defaultModel(string $provider): string { return (string) (self::CATALOG[$provider]['model'] ?? ''); } public static function defaultModels(): array { return array_map(fn(array $entry) => (string) $entry['model'], self::CATALOG); } public static function userProviders(): array { $named = array_values(array_diff(self::providers(), ['custom'])); return self::baseUrl() !== '' ? [...$named, 'custom'] : $named; } public static function baseUrlFor(string $provider): string { $entry = self::CATALOG[$provider] ?? ['base' => '']; $own = self::baseUrl(); if ($provider === 'custom') { return $own; } if (($entry['local'] ?? false) && $own !== '') { return $own; } return (string) $entry['base']; } public static function keyless(string $provider): bool { return (bool) (self::CATALOG[$provider]['keyless'] ?? false); } public static function addressable(string $provider): bool { return $provider === 'custom' || (self::CATALOG[$provider]['local'] ?? false); } public static function baseUrl(): string { return self::endpointBase((string) self::setting('base_url', '')); } public static function endpointBase(string $url): string { $url = rtrim(trim($url), '/'); return (string) preg_replace('#/(chat/completions|completions|models|messages)$#i', '', $url); } public static function keyMode(): string { $mode = (string) self::setting('key_mode', 'panel'); return in_array($mode, self::KEY_MODES, true) ? $mode : 'panel'; } public static function allowWrites(): bool { return (bool) self::setting('allow_writes', true); } public static function limit(): array { return ['messages' => max(1, min(120, (int) self::setting('limit_messages', 8))), 'minutes' => max(1, min(1440, (int) self::setting('limit_minutes', 1)))]; /* 122283 */ } public static function maxSteps(): int { return max(1, min(30, (int) self::setting('max_steps', 12))); } public static function timeBudget(): int { return max(30, min(600, (int) self::setting('time_budget', 240))); } public static function systemPrompt(): string { $prompt = trim((string) self::setting('system', '')); return $prompt !== '' ? $prompt : self::DEFAULT_PROMPT; } public static function panelKey(?string $provider = null): ?string { $keys = self::blob()['keys'] ?? []; $stored = is_array($keys) ? $keys[$provider ?? self::provider()] ?? null : null; if (!is_string($stored) || $stored === '') { return null; } try { return Crypt::decryptString($stored); } catch (Throwable) { return null; } } public static function setPanelKey(string $provider, ?string $key): void { $blob = self::blob(); $keys = is_array($blob['keys'] ?? null) ? $blob['keys'] : []; if ($key === null || trim($key) === '') { unset($keys[$provider]); } else { $keys[$provider] = Crypt::encryptString(trim($key)); } self::write(['keys' => $keys]); } public static function panelKeys(): array { $held = []; foreach (self::providers() as $provider) { $held[$provider] = self::panelKey($provider) !== null; } return $held; } public static function keyFor(User $user, bool $preferOwn = false): ?array { $own = self::userKey($user); $panel = self::panelKey(); $mineProvider = self::userProvider($user); if ($own === null && $panel === null && self::keyless(self::provider())) { return ['key' => 'local', 'source' => 'panel', 'provider' => self::provider(), 'model' => self::model()]; } $mine = $own === null ? null : ['key' => $own, 'source' => 'user', 'provider' => $mineProvider, 'model' => self::userModel($user) ?? self::modelFor($mineProvider)]; $ours = $panel === null ? null : ['key' => $panel, 'source' => 'panel', 'provider' => self::provider(), 'model' => self::model()]; return match (self::keyMode()) { 'user' => $mine, 'choice' => $preferOwn && $mine !== null ? $mine : $ours ?? $mine, default => $ours, }; } public static function preferences(User $user): array { $stored = $user->dezerx_preferences[self::USER_KEY] ?? []; return is_array($stored) ? $stored : []; } public static function setPreferences(User $user, array $values): void { $user->forceFill(['dezerx_preferences' => [...$user->dezerx_preferences ?? [], self::USER_KEY => [...self::preferences($user), ...$values]]])->saveOrFail(); } public static function userKey(User $user): ?string { $stored = self::preferences($user)['key'] ?? null; if (!is_string($stored) || $stored === '') { return null; } try { return Crypt::decryptString($stored); } catch (Throwable) { return null; } } public static function userProvider(User $user): string { $provider = (string) (self::preferences($user)['provider'] ?? ''); return isset(self::CATALOG[$provider]) ? $provider : self::provider(); } public static function userModel(User $user): ?string { $model = trim((string) (self::preferences($user)['model'] ?? '')); return $model !== '' ? $model : null; } public static function prefersOwnKey(User $user): bool { return (bool) (self::preferences($user)['own'] ?? false); } public static function askFirst(User $user): bool { return (bool) (self::preferences($user)['askFirst'] ?? true); } public static function payload(?User $user): ?array { if (!self::enabled() || $user === null) { return null; } $mode = self::keyMode(); $hasOwn = self::userKey($user) !== null; $hasPanel = self::panelKey() !== null; return ['keyMode' => $mode, 'hasOwnKey' => $hasOwn, 'hasPanelKey' => $hasPanel, 'ready' => self::keyless(self::provider()) || match ($mode) { 'user' => $hasOwn, 'choice' => $hasOwn || $hasPanel, default => $hasPanel, }, 'canBringKey' => $mode !== 'panel', 'provider' => self::provider(), 'model' => self::model(), 'providerLabels' => self::providerLabels(), 'userProviders' => self::userProviders(), 'ownProvider' => $hasOwn ? self::userProvider($user) : self::provider(), 'ownModel' => self::userModel($user) ?? '', 'own' => self::prefersOwnKey($user), 'defaultModels' => self::defaultModels(), 'keylessProviders' => array_values(array_filter(self::providers(), self::keyless(...))), 'writes' => self::allowWrites(), 'askFirst' => self::askFirst($user), 'limit' => self::limit()]; } public static function sanitiseProvider(mixed $value): ?string { return is_string($value) && isset(self::CATALOG[$value]) ? $value : null; } public static function sanitiseKeyMode(mixed $value): ?string { return is_string($value) && in_array($value, self::KEY_MODES, true) ? $value : null; } public static function sanitiseBaseUrl(mixed $value): ?string { $url = trim((string) $value); if ($url === '') { return ''; } return preg_match('#^https?://[^\s]+$#i', $url) === 1 ? self::endpointBase(mb_substr($url, 0, 300)) : null; } public static function write(array $values): void { Settings::put(self::SETTING_KEY, [...self::blob(), ...$values]); } public static function blob(): array { return Settings::get(self::SETTING_KEY) ?? []; } private static function setting(string $key, mixed $fallback = null): mixed { return self::blob()[$key] ?? $fallback; } } 